## Module: IAM (`modules/iam/`)

### `modules/iam/variables.tf`

```hcl
variable "name_prefix" {
  description = "Prefix for IAM resource names"
  type        = string
}

variable "environment" {
  description = "Environment name (dev/prod)"
  type        = string
}

variable "bucket_arn" {
  description = "ARN of the S3 bucket the service account can access"
  type        = string
}

variable "oidc_provider_arn" {
  description = "EKS OIDC provider ARN for IRSA trust (prod least-privilege)"
  type        = string
  default     = null
}

variable "oidc_provider_url" {
  description = "EKS OIDC provider URL (without https://)"
  type        = string
  default     = null
}

variable "service_account_namespace" {
  description = "Kubernetes namespace of the service account"
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "Kubernetes service account name"
  type        = string
  default     = "app-sa"
}

variable "tags" {
  description = "Common resource tags"
  type        = map(string)
  default     = {}
}
```

### `modules/iam/main.tf`

```hcl
# ---------------------------------------------------------------
# Least-privilege policy: scoped to the specific bucket only.
# No wildcard actions (AC4).
# ---------------------------------------------------------------
data "aws_iam_policy_document" "app_access" {
  statement {
    sid    = "BucketList"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [var.bucket_arn]
  }

  statement {
    sid    = "ObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = ["${var.bucket_arn}/*"]
  }
}

resource "aws_iam_policy" "app_access" {
  name        = "${var.name_prefix}-app-access"
  description = "Least-privilege S3 access for ${var.environment}"
  policy      = data.aws_iam_policy_document.app_access.json
  tags        = var.tags
}

# ---------------------------------------------------------------
# Trust policy: OIDC (IRSA) when provider given (prod),
# otherwise EC2/service assume for dev.
# ---------------------------------------------------------------
data "aws_iam_policy_document" "assume_role" {
  dynamic "statement" {
    for_each = var.oidc_provider_arn != null ? [1] : []
    content {
      effect  = "Allow"
      actions = ["sts:AssumeRoleWithWebIdentity"]

      principals {
        type        = "Federated"
        identifiers = [var.oidc_provider_arn]
      }

      condition {
        test     = "StringEquals"
        variable = "${var.oidc_provider_url}:sub"
        values   = ["system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"]
      }

      condition {
        test     = "StringEquals"
        variable = "${var.oidc_provider_url}:aud"
        values   = ["sts.amazonaws.com"]
      }
    }
  }

  # Fallback for dev: EC2 service principal
  dynamic "statement" {
    for_each = var.oidc_provider_arn == null ? [1] : []
    content {
      effect  = "Allow"
      actions = ["sts:AssumeRole"]
      principals {
        type        = "Service"
        identifiers = ["ec2.amazonaws.com"]
      }
    }
  }
}

resource "aws_iam_role" "service_account" {
  name               = "${var.name_prefix}-sa-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "app_access" {
  role       = aws_iam_role.service_account.name
  policy_arn = aws_iam_policy.app_access.arn
}

# ---------------------------------------------------------------
# Dev only: programmatic-access IAM user
# ---------------------------------------------------------------
resource "aws_iam_user" "programmatic" {
  count = var.environment == "dev" ? 1 : 0
  name  = "${var.name_prefix}-programmatic"
  tags  = var.tags
}

resource "aws_iam_user_policy_attachment" "programmatic" {
  count      = var.environment == "dev" ? 1 : 0
  user       = aws_iam_user.programmatic[0].name
  policy_arn = aws_iam_policy.app_access.arn
}

resource "aws_iam_access_key" "programmatic" {
  count = var.environment == "dev" ? 1 : 0
  user  = aws_iam_user.programmatic[0].name
}
```

### `modules/iam/outputs.tf`

```hcl
output "role_arn" {
  description = "ARN of the service account role"
  value       = aws_iam_role.service_account.arn
}

output "policy_arn" {
  description = "ARN of the least-privilege policy"
  value       = aws_iam_policy.app_access.arn
}

output "access_key_id" {
  description = "Dev programmatic access key ID"
  value       = var.environment == "dev" ? aws_iam_access_key.programmatic[0].id : null
  sensitive   = true
}

output "secret_access_key" {
  description = "Dev programmatic secret access key"
  value       = var.environment == "dev" ? aws_iam_access_key.programmatic[0].secret : null
  sensitive   = true
}
```

