## Root Module

### `providers.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    sops = {
      source  = "carlpett/sops"
      version = "~> 1.0"
    }
  }

  # Remote state with per-workspace isolation (AC7)
  backend "s3" {
    bucket               = "my-tf-state-bucket"
    key                  = "canonical/terraform.tfstate"
    region               = "us-east-1"
    dynamodb_table       = "tf-locks"
    workspace_key_prefix = "env"
    encrypt              = true
  }
}

provider "aws" {
  region = var.region
  default_tags {
    tags = {
      ManagedBy = "terraform"
      Project   = "canonical"
    }
  }
}

# Aliased provider for cross-region replication
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# SOPS provider to decrypt secrets at plan/apply time
provider "sops" {}
```

### `variables.tf`

```hcl
variable "environment" {
  description = "Environment name"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be dev or prod."
  }
}

variable "region" {
  description = "Primary AWS region"
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "Replica region for S3 CRR"
  type        = string
  default     = "us-west-2"
}

variable "bucket_name" {
  description = "S3 bucket name"
  type        = string
}

variable "enable_replication" {
  description = "Enable S3 cross-region replication"
  type        = bool
  default     = false
}

# RDS sizing
variable "db_instance_class" {
  type = string
}

variable "db_multi_az" {
  type    = bool
  default = false
}

variable "db_backup_retention" {
  type    = number
  default = 7
}

# Networking (assumed provided by a VPC module / data source)
variable "subnet_ids" {
  type = list(string)
}

variable "vpc_security_group_ids" {
  type = list(string)
}

# OIDC (prod IRSA)
variable "oidc_provider_arn" {
  type    = string
  default = null
}

variable "oidc_provider_url" {
  type    = string
  default = null
}

# Secret file path (SOPS-encrypted)
variable "sops_secrets_file" {
  description = "Path to SOPS-encrypted secrets YAML"
  type        = string
  default     = "secrets.enc.yaml"
}
```

### `main.tf`

```hcl
locals {
  name_prefix = "canonical-${var.environment}"
  common_tags = {
    Environment = var.environment
    Project     = "canonical"
  }
}

# Decrypt DB credentials from SOPS (AC3: never plaintext in Git)
data "sops_file" "secrets" {
  source_file = var.sops_secrets_file
}

module "s3" {
  source = "./modules/s3"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  bucket_name        = var.bucket_name
  environment        = var.environment
  enable_replication = var.enable_replication
  replica_region     = var.replica_region
  tags               = local.common_tags
}

module "rds" {
  source = "./modules/rds"

  identifier              = "${local.name_prefix}-postgres"
  environment             = var.environment
  instance_class          = var.db_instance_class
  multi_az                = var.db_multi_az
  storage_encrypted       = true
  backup_retention_period = var.db_backup_retention

  db_username = data.sops_file.secrets.data["db_username"]
  db_password = data.sops_file.secrets.data["db_password"]

  subnet_ids             = var.subnet_ids
  vpc_security_group_ids = var.vpc_security_group_ids

  tags = local.common_tags
}

module "iam" {
  source = "./modules/iam"

  name_prefix = local.name_prefix
  environment = var.environment
  bucket_arn  = module.s3.bucket_arn

  oidc_provider_arn = var.oidc_provider_arn
  oidc_provider_url = var.oidc_provider_url

  tags = local.common_tags
}
```

### `outputs.tf`

```hcl
output "bucket_arn" {
  value = module.s3.bucket_arn
}

output "rds_endpoint" {
  value = module.rds.db_endpoint
}

output "db_connection_string" {
  value     = module.rds.connection_string
  sensitive = true
}

output "service_account_role_arn" {
  value = module.iam.role_arn
}
```

